return [{ json: { text: decodedText, sha: items[0].json.sha, path: items[0].json.path } }];

// Atomic GitHub create-or-update with retry on 409 SHA conflict.
// Replaces the 3-node Get-SHA -> Edit/Create chain that race-conditioned on parallel writes.

const params = $('Set Parameters').item.json;
const filename = params.filename;
const content = params.content;
const commitMessage = params.commitMessage;
const owner = 'F4bse-94';
const repo = 'google-ads-memory';

if (!filename || !commitMessage || content === undefined) {
  throw new Error(`Missing required params: filename=${filename}, commitMessage=${commitMessage}, content=${content === undefined ? 'undefined' : 'set'}`);
}

const apiUrl = `https://api.github.com/repos/${owner}/${repo}/contents/${filename.split('/').map(encodeURIComponent).join('/')}`;
const contentBase64 = Buffer.from(content, 'utf8').toString('base64');
const maxRetries = 5;

async function getStatus(err) {
  return err.httpCode || err.statusCode || (err.response && err.response.status) || (err.cause && err.cause.statusCode) || null;
}

let lastError = null;
for (let attempt = 1; attempt <= maxRetries; attempt++) {
  // Step 1: try to fetch current SHA. 404 means file does not exist (create path).
  let sha = null;
  let exists = false;
  try {
    const getRes = await this.helpers.httpRequestWithAuthentication.call(
      this,
      'githubApi',
      {
        method: 'GET',
        url: apiUrl,
        json: true,
        headers: { Accept: 'application/vnd.github+json' }
      }
    );
    sha = getRes.sha;
    exists = true;
  } catch (e) {
    const status = await getStatus(e);
    if (status === 404 || status === '404') {
      exists = false;
    } else {
      throw new Error(`GET sha failed (status=${status}, attempt=${attempt}): ${e.message}`);
    }
  }

  // Step 2: PUT (create or update). On 409/422 we retry with refetched SHA.
  try {
    const body = { message: commitMessage, content: contentBase64 };
    if (exists && sha) body.sha = sha;
    const putRes = await this.helpers.httpRequestWithAuthentication.call(
      this,
      'githubApi',
      {
        method: 'PUT',
        url: apiUrl,
        body,
        json: true,
        headers: { Accept: 'application/vnd.github+json' }
      }
    );
    return [{ json: {
      ok: true,
      attempt,
      action: exists ? 'edited' : 'created',
      filename,
      commit_sha: putRes.commit && putRes.commit.sha,
      content_sha: putRes.content && putRes.content.sha,
      commit_url: putRes.commit && putRes.commit.html_url,
      message: commitMessage
    } }];
  } catch (e) {
    const status = await getStatus(e);
    lastError = e;
    if ((status === 409 || status === '409' || status === 422 || status === '422') && attempt < maxRetries) {
      const backoffMs = 200 * Math.pow(2, attempt - 1) + Math.floor(Math.random() * 200);
      await new Promise(r => setTimeout(r, backoffMs));
      continue;
    }
    throw new Error(`PUT failed (status=${status}, attempt=${attempt}/${maxRetries}): ${e.message}`);
  }
}
throw lastError || new Error(`Atomic edit failed after ${maxRetries} retries`);
